package icc.pap.u1.patrones2;

public class App {
   public static void main(String[] args) {
        System.out.println("=== Ejecutando Patron Singleton ===");
        runSingleton();
    }

    
    
     
    public static void runSingleton() {
        // Intentamos obtener la primera instancia
        SingletonDemo obj1 = SingletonDemo.obtenerInstancia();
        obj1.mostrarMensaje();

        // Intentamos obtener una segunda instancia
        SingletonDemo obj2 = SingletonDemo.obtenerInstancia();
        obj2.mostrarMensaje();

        // Verificamos que ambas variables apunten exactamente al mismo objeto en memoria
        if (obj1 == obj2) {
            System.out.println("\nSi apunta.");
        } else {
            System.out.println("\nno apuenta es probable que se crearon de forma diferente.");
        }
    }
}
